# Terraform: SageMaker Feature Group offline store encrypted with a KMS key
resource "aws_sagemaker_feature_group" "<example_resource_name>" {
  feature_group_name             = "<example_resource_name>"
  record_identifier_feature_name = "<id_feature>"
  event_time_feature_name        = "<event_time_feature>"
  role_arn                       = "<example_resource_arn>"

  feature_definition {
    feature_name = "<id_feature>"
    feature_type = "Integral"
  }
  feature_definition {
    feature_name = "<event_time_feature>"
    feature_type = "String"
  }

  offline_store_config {
    s3_storage_config {
      s3_uri     = "s3://<bucket>/<prefix>"
      kms_key_id = "<kms_key_arn>"  # Critical: encrypts the offline store S3 data with the KMS key
    }
  }
}
```
